namespace UnityEngine
{
    public class SerializeField : System.Attribute { }

    public struct Vector3
    {
        public float x, y, z;
        public Vector3(float x, float y, float z) { this.x = x; this.y = y; this.z = z; }
        public static Vector3 zero => default;
        public float sqrMagnitude => x * x + y * y + z * z;
        public float magnitude => System.MathF.Sqrt(sqrMagnitude);
        public static Vector3 operator -(Vector3 a, Vector3 b) => new Vector3(a.x - b.x, a.y - b.y, a.z - b.z);
        public static Vector3 operator +(Vector3 a, Vector3 b) => new Vector3(a.x + b.x, a.y + b.y, a.z + b.z);
        public static Vector3 operator *(Vector3 a, float d) => new Vector3(a.x * d, a.y * d, a.z * d);
        public static float Distance(Vector3 a, Vector3 b) => (a - b).magnitude;
        public static float SqrMagnitude(Vector3 v) => v.sqrMagnitude;
        public static float Dot(Vector3 a, Vector3 b) => a.x * b.x + a.y * b.y + a.z * b.z;
    }

    public static class Mathf
    {
        public const float Infinity = float.PositiveInfinity;
        public static float Sqrt(float f) => System.MathF.Sqrt(f);
        public static float Abs(float f) => System.MathF.Abs(f);
        public static float Min(float a, float b) => a < b ? a : b;
        public static float Max(float a, float b) => a > b ? a : b;
    }

    public class GameObject
    {
        private bool active = true;
        public Transform transform { get; }
        public bool activeInHierarchy => active;
        public bool activeSelf => active;
        public GameObject() { transform = new Transform(this); }
        public void SetActive(bool value) { active = value; }
    }

    public class Component
    {
        internal GameObject owner;
        public GameObject gameObject => owner;
        public Transform transform => owner.transform;
    }

    public class Transform : Component
    {
        internal Transform(GameObject go) { owner = go; }
        public Vector3 position { get; set; }
    }

    public class MonoBehaviour : Component
    {
        public bool enabled = true;
        public MonoBehaviour() { owner = new GameObject(); }
    }

    public static class Time { public static float deltaTime = 0.016f; public static float time; }
}

