        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    // Returns null when WriteTimer(seconds) produced exactly `expected`.
    private static string Check(int seconds, string expected)
    {
        var buffer = new char[16];
        for (int i = 0; i < buffer.Length; i++) buffer[i] = '#';
        int n = HudFormat.WriteTimer(seconds, buffer);
        if (n < 0 || n > buffer.Length) return "입력 " + seconds + ": 반환 길이가 범위를 벗어남: " + n;
        string got = new string(buffer, 0, n);
        return got == expected ? null : "입력 " + seconds + ": 기대 \"" + expected + "\", 결과 \"" + got + "\" (길이 " + n + ")";
    }

    public static void Main()
    {
        Run("zero", () => Check(0, "00:00"));
        Run("under-one-minute", () => Check(5, "00:05") ?? Check(59, "00:59"));
        Run("minute-boundary", () => Check(60, "01:00") ?? Check(61, "01:01") ?? Check(754, "12:34") ?? Check(5999, "99:59"));
        Run("three-digit-minutes", () => Check(6000, "100:00") ?? Check(59999, "999:59") ?? Check(60000, "1000:00"));
        Run("negative-clamps-to-zero", () => Check(-1, "00:00") ?? Check(int.MinValue, "00:00"));
        Run("int-max", () => Check(int.MaxValue, "35791394:07"));
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(777);
            for (int i = 0; i < 2000; i++)
            {
                int t = i < 1000 ? rng.Next(0, 7300) : rng.Next();
                string expected = (t / 60).ToString("00") + ":" + (t % 60).ToString("00");
                string err = Check(t, expected);
                if (err != null) return err;
            }
            return null;
        });
        Run("zero-alloc", () =>
        {
            var buffer = new char[16];
            // Inputs go up to 33,269 minutes so that number-to-string shortcuts for small values cannot hide an allocation.
            long allocated = 0; int total = 0, expectedPerRound = 0;
            for (int t = 0; t < 400; t++)
            {
                int digits = 2;
                for (int m = t * 5003 / 6000; m > 0; m /= 10) digits++;
                expectedPerRound += digits + 3;
            }
            for (int round = 0; round < 200; round++)
            {
                bool measured = round >= 100; // first 100 rounds are warm-up
                long before = System.GC.GetAllocatedBytesForCurrentThread();
                for (int t = 0; t < 400; t++) total += HudFormat.WriteTimer(t * 5003, buffer);
                long after = System.GC.GetAllocatedBytesForCurrentThread();
                if (measured) allocated += after - before;
            }
            if (total != 200 * expectedPerRound) return "할당 측정 중 반환 길이의 합이 잘못됨: " + total;
            return allocated == 0 ? null : "측정 구간(호출 40,000회)에서 " + allocated + " B가 할당됨";
        });
    }
}

