using System;
using System.Collections;
using System.Collections.Generic;

/// <summary>
/// Fixed-capacity, unordered list of the projectiles that are alive this frame.
/// Elements live in one array; removing swaps the last element into the hole.
/// </summary>
public sealed class ActiveList<T> : IEnumerable<T>
{
    private readonly T[] _items;
    private int _count;
    private int _version;   // bumped by every Add / RemoveAtSwapBack

    public ActiveList(int capacity)
    {
        if (capacity < 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _items = new T[capacity];
    }

    public int Count => _count;

    public T this[int index]
    {
        get
        {
            if ((uint)index >= (uint)_count) throw new ArgumentOutOfRangeException(nameof(index));
            return _items[index];
        }
    }

    public void Add(T item)
    {
        if (_count == _items.Length) throw new InvalidOperationException("ActiveList is full.");
        _items[_count++] = item;
        _version++;
    }

    public void RemoveAtSwapBack(int index)
    {
        if ((uint)index >= (uint)_count) throw new ArgumentOutOfRangeException(nameof(index));
        _count--;
        _items[index] = _items[_count];
        _items[_count] = default(T);
        _version++;
    }

    /// <summary>
    /// `foreach (var p in list)` binds to this method by pattern: the compiler only needs
    /// a public GetEnumerator() whose result has MoveNext() and Current.
    /// Returning the struct itself (not IEnumerator&lt;T&gt;) means nothing is boxed.
    /// </summary>
    public Enumerator GetEnumerator()
    {
        return new Enumerator(this);
    }

    // Interface paths (LINQ, methods taking IEnumerable<T>) still work,
    // but converting the struct to the interface boxes it: one allocation per call.
    IEnumerator<T> IEnumerable<T>.GetEnumerator()
    {
        return new Enumerator(this);
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return new Enumerator(this);
    }

    /// <summary>Value-type cursor over an ActiveList. Each foreach gets its own copy.</summary>
    public struct Enumerator : IEnumerator<T>
    {
        private readonly ActiveList<T> _list;
        private readonly int _version;   // list version when this enumerator was created
        private int _index;              // index of the next element to yield
        private T _current;

        internal Enumerator(ActiveList<T> list)
        {
            _list = list;
            _version = list._version;
            _index = 0;
            _current = default(T);
        }

        public T Current => _current;

        object IEnumerator.Current => _current;

        public bool MoveNext()
        {
            if (_version != _list._version)
                throw new InvalidOperationException("ActiveList was modified during enumeration.");

            if (_index < _list._count)
            {
                _current = _list._items[_index];
                _index++;
                return true;
            }

            _current = default(T);
            return false;
        }

        public void Reset()
        {
            if (_version != _list._version)
                throw new InvalidOperationException("ActiveList was modified during enumeration.");
            _index = 0;
            _current = default(T);
        }

        public void Dispose()
        {
            // Nothing to release. foreach still calls this, without boxing the struct.
        }
    }
}

