problems.solutionCode:
using System;

/// <summary>Stable reference to one buff: a slot number plus the slot's generation at creation time.</summary>
public readonly struct BuffHandle
{
    public readonly int Slot;
    public readonly int Generation;

    public BuffHandle(int slot, int generation)
    {
        Slot = slot;
        Generation = generation;
    }
}

/// <summary>
/// Fixed-capacity buff storage in struct-of-arrays form.
/// Live buffs are packed in [0, Count) of the dense arrays; removal swaps the last buff into the hole.
/// Handles stay valid across those moves because they name a slot, not a dense index.
/// </summary>
public sealed class BuffTable
{
    // Dense, parallel arrays. Index d in [0, _count) describes one live buff.
    private readonly int[] _buffIds;
    private readonly float[] _remaining;
    private readonly int[] _stacks;
    private readonly int[] _denseToSlot;

    // Per-slot bookkeeping, indexed by BuffHandle.Slot.
    private readonly int[] _slotToDense;   // dense index, or -1 while the slot is free
    private readonly int[] _generations;   // starts at 1, so default(BuffHandle) never matches

    // Stack of free slot numbers.
    private readonly int[] _freeSlots;
    private int _freeCount;

    private int _count;

    public BuffTable(int capacity)
    {
        if (capacity < 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _buffIds = new int[capacity];
        _remaining = new float[capacity];
        _stacks = new int[capacity];
        _denseToSlot = new int[capacity];
        _slotToDense = new int[capacity];
        _generations = new int[capacity];
        _freeSlots = new int[capacity];
        for (int slot = 0; slot < capacity; slot++)
        {
            _slotToDense[slot] = -1;
            _generations[slot] = 1;
            _freeSlots[slot] = capacity - 1 - slot;   // slot 0 is handed out first
        }
        _freeCount = capacity;
    }

    public int Count => _count;
    public int Capacity => _buffIds.Length;

    /// <summary>Adds a buff. Returns false (and a default handle) when the table is full.</summary>
    public bool TryAdd(int buffId, float duration, int stacks, out BuffHandle handle)
    {
        if (_freeCount == 0)
        {
            handle = default(BuffHandle);
            return false;
        }

        int slot = _freeSlots[--_freeCount];
        int dense = _count++;
        _buffIds[dense] = buffId;
        _remaining[dense] = duration;
        _stacks[dense] = stacks;
        _denseToSlot[dense] = slot;
        _slotToDense[slot] = dense;
        handle = new BuffHandle(slot, _generations[slot]);
        return true;
    }

    /// <summary>True while the buff this handle was created for is still in the table.</summary>
    public bool IsAlive(BuffHandle handle)
    {
        return (uint)handle.Slot < (uint)_generations.Length
            && _generations[handle.Slot] == handle.Generation
            && _slotToDense[handle.Slot] >= 0;
    }

    /// <summary>Reads a live buff. Returns false for stale, default or out-of-range handles.</summary>
    public bool TryGet(BuffHandle handle, out int buffId, out float remaining, out int stacks)
    {
        if (!IsAlive(handle))
        {
            buffId = 0;
            remaining = 0f;
            stacks = 0;
            return false;
        }

        int dense = _slotToDense[handle.Slot];
        buffId = _buffIds[dense];
        remaining = _remaining[dense];
        stacks = _stacks[dense];
        return true;
    }

    /// <summary>Removes a live buff in O(1). Returns false for stale, default or out-of-range handles.</summary>
    public bool Remove(BuffHandle handle)
    {
        if (!IsAlive(handle)) return false;
        RemoveDense(_slotToDense[handle.Slot]);
        return true;
    }

    /// <summary>
    /// Subtracts deltaTime from every live buff and removes those whose remaining time is 0 or less.
    /// Returns how many buffs expired.
    /// </summary>
    public int Tick(float deltaTime)
    {
        int expired = 0;
        // Backwards: the buff swapped into a hole comes from the end, which was already processed.
        for (int dense = _count - 1; dense >= 0; dense--)
        {
            _remaining[dense] -= deltaTime;
            if (_remaining[dense] <= 0f)
            {
                RemoveDense(dense);
                expired++;
            }
        }
        return expired;
    }

    /// <summary>Sum of the stacks of all live buffs with this buffId.</summary>
    public int TotalStacks(int buffId)
    {
        int total = 0;
        for (int dense = 0; dense < _count; dense++)
        {
            if (_buffIds[dense] == buffId) total += _stacks[dense];
        }
        return total;
    }

    private void RemoveDense(int dense)
    {
        int slot = _denseToSlot[dense];
        int last = --_count;

        if (dense != last)
        {
            // Move the last live buff into the hole, column by column, and repoint its slot.
            int movedSlot = _denseToSlot[last];
            _buffIds[dense] = _buffIds[last];
            _remaining[dense] = _remaining[last];
            _stacks[dense] = _stacks[last];
            _denseToSlot[dense] = movedSlot;
            _slotToDense[movedSlot] = dense;
        }

        // Retire the slot: every handle issued for it so far stops matching.
        _slotToDense[slot] = -1;
        _generations[slot]++;
        if (_generations[slot] <= 0) _generations[slot] = 1;   // wrap-around: skip 0 and negatives
        _freeSlots[_freeCount++] = slot;
    }
}

