using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

/// <summary>
/// Writes "key=value" lines to a save stream.
/// The writer owns the stream: disposing the writer flushes and closes it.
/// </summary>
public sealed class SaveWriter : IDisposable
{
    /// <summary>Writers that are open right now. The quit dialog waits until this is 0.</summary>
    public static int OpenCount { get; private set; }

    private readonly Stream _stream;
    private bool _disposed;

    public SaveWriter(Stream stream)
    {
        if (stream == null) throw new ArgumentNullException(nameof(stream));
        _stream = stream;
        OpenCount++;
    }

    public void WriteEntry(string key, int value)
    {
        if (_disposed) throw new ObjectDisposedException(nameof(SaveWriter));
        if (key == null) throw new ArgumentNullException(nameof(key));
        byte[] bytes = Encoding.UTF8.GetBytes(key + "=" + value + "\n");
        _stream.Write(bytes, 0, bytes.Length);
    }

    // Idempotent: only the first call releases anything.
    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        OpenCount--;
        _stream.Flush();
        _stream.Dispose();
    }

    // No finalizer: this class holds only managed objects. A finalizer runs at a
    // time the GC chooses and must not touch other managed objects such as the stream.
}

public static class SaveGame
{
    /// <summary>
    /// Writes every entry to the stream, then closes it.
    /// If an entry is invalid the exception goes to the caller, and the stream must still be closed.
    /// </summary>
    public static void Save(Stream stream, IReadOnlyList<KeyValuePair<string, int>> entries)
    {
        // using = try/finally: Dispose runs on the normal path and when WriteEntry throws.
        using (var writer = new SaveWriter(stream))
        {
            for (int i = 0; i < entries.Count; i++)
            {
                writer.WriteEntry(entries[i].Key, entries[i].Value);
            }
        }
    }
}

